            AsrChatState.AsrText,
            systemPrompt: "你是一个中文语音助手，请简洁、自然地回答用户的问题。",
            onDeltaCallback: "reply_delta",
            onCompletedCallback: "reply_done",
            onErrorCallback: "reply_error");
