    Scene.GetGuiControl("Heard")?.SetValue(RealtimeVoiceText);
}

if (IsRealtimeVoiceEvent && RealtimeVoiceCallbackName == "voice_delta")
{
    Scene.GetGuiControl("Reply")?.SetValue(RealtimeVoiceAccumulatedText);
